#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int levenshtein_distance(const char *s1, const char *s2) {
    int m = strlen(s1);
    int n = strlen(s2);
    int **dp = (int **)malloc((m + 1) * sizeof(int *));
    for (int i = 0; i <= m; i++) {
        dp[i] = (int *)malloc((n + 1) * sizeof(int));
    }

    for (int i = 0; i <= m; i++) {
        dp[i][0] = i;
    }
    for (int j = 0; j <= n; j++) {
        dp[0][j] = j;
    }

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            int cost = (s1[i - 1] == s2[j - 1]) ? 0 : 1;
            dp[i][j] = min(min(dp[i - 1][j] + 1, dp[i][j - 1] + 1), dp[i - 1][j - 1] + cost);
        }
    }

    int distance = dp[m][n];
    for (int i = 0; i <= m; i++) {
        free(dp[i]);
    }
    free(dp);
    return distance;
}

int min(int a, int b) {
    return (a < b) ? a : b;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }

    char *str1 = argv[1];
    char *str2 = argv[2];

    if (strlen(str1) > 40 || strlen(str2) > 40) {
        printf("TOO_LONG\n");
        return 0;
    }

    int distance = levenshtein_distance(str1, str2);
    printf("%d\n", distance);

    return 0;
}
